import csv, sys
from collections import Counter, defaultdict
cat_path, disp_path = sys.argv[1], sys.argv[2]
def num(s):
    return float(s.strip().replace(',', '.'))
cat = {}
ean = {}
with open(cat_path, newline='') as f:
    for r in csv.DictReader(f):
        r = {k: v.strip() for k, v in r.items()}
        cat[r['product_id']] = r
        ean[r['ean_code']] = r['product_id']
print("catalog products:", len(cat), "unique eans:", len(ean))
disp = []
with open(disp_path, newline='') as f:
    for r in csv.DictReader(f):
        disp.append({k: v.strip() for k, v in r.items()})
print("dispatch rows:", len(disp))
# ids
ids = [d['dispatch_id'] for d in disp]
print("unique dispatch ids:", len(set(ids)))
# unmatched product ids
for d in disp:
    if d['product_id'] not in cat:
        print("UNMATCHED", d, "-> via EAN:", ean.get(d['product_id']))
# weight consistency
for d in disp:
    pid = d['product_id'] if d['product_id'] in cat else ean.get(d['product_id'])
    p = cat[pid]
    q = int(d['quantity'])
    w = float(d['total_weight_kg'])
    exp = q * num(p['unit_weight_kg'])
    if abs(exp - w) > 0.011:
        print("WEIGHT MISMATCH", d, "expected", round(exp, 3), p['name'])
# months
print(Counter(d['timestamp'][:7] for d in disp))
# duplicates on (timestamp, product, qty, weight)
key = Counter((d['timestamp'], d['product_id'], d['quantity'], d['total_weight_kg']) for d in disp)
dups = {k: v for k, v in key.items() if v > 1}
print("duplicate keys:", len(dups), "extra rows:", sum(v - 1 for v in dups.values()))
print("dup dates:", sorted(Counter(k[0][:10] for k in dups).items()))
# rows in 07-10..07-14 that are NOT duplicated
for d in disp:
    if '2023-07-10' <= d['timestamp'][:10] <= '2023-07-14':
        k = (d['timestamp'], d['product_id'], d['quantity'], d['total_weight_kg'])
        if key[k] == 1:
            print("non-dup in dup window:", d)
# same timestamp groups (not exact dups)
ts = defaultdict(list)
for d in disp:
    ts[d['timestamp']].append(d)
for t, lst in ts.items():
    if len(lst) > 1 and len(set((x['product_id'], x['quantity']) for x in lst)) > 1:
        print("MULTI at", t, [(x['dispatch_id'], x['product_id'], x['quantity']) for x in lst])
# hour distribution
print(sorted(Counter(int(d['timestamp'][11:13]) for d in disp).items()))
# quantity stats per category
qs = defaultdict(list)
for d in disp:
    pid = d['product_id'] if d['product_id'] in cat else ean.get(d['product_id'])
    qs[cat[pid]['storage_category']].append(int(d['quantity']))
for c, l in qs.items():
    print(c, len(l), min(l), max(l), sorted(l)[-5:])
